"""Removal of customer credentials from config data before it leaves the process.

Customer configuration is reported to two outbound channels: product telemetry
and OpenTelemetry tracing spans. Both serialize config that can contain
credentials, because customers sometimes write a literal secret into a config
file instead of referencing an environment variable, and the validation that
rejects that runs too late to help.

Rather than trusting the shape of a value, anything credential-shaped is dropped
on the way out. There is deliberately **no debug escape hatch**: unlike
conversation content, which a developer may legitimately need to inspect
locally, a credential has no reason to be emitted at any verbosity.
"""

from typing import Any, Dict, FrozenSet, Tuple

from rasa.utils.url_tools import strip_url_credentials

# Config keys whose values must never leave the process.
#
# Deliberately NOT `rasa.shared.constants.SENSITIVE_DATA`: that list governs
# YAML env-var expansion, not outbound reporting, and its effect here is the opposite of
# what is needed. Keys on it survive in memory as the literal "${VAR}"
# placeholder, while the keys it omits (`token`, `redis_password`, ...) have
# already been expanded to their real value by the time we report -- so the
# fields most likely to hold a live secret are exactly the ones it leaves out.
REDACTED_CONFIG_KEYS = frozenset(
    {
        "api_key",
        "aws_access_key_id",
        "aws_secret_access_key",
        "aws_session_token",
        "azure_ad_token",
        "certificate_password",
        # `client_id` carries no analytics value and the codebase already
        # classifies it as sensitive, so follow that rather than second-guess it.
        "client_id",
        "client_secret",
        # Bare and non-underscored spellings seen carrying real credentials in
        # customer configs. None of them has analytics value.
        "api",
        "apikey",
        "authorization",
        "key",
        "license",
        "password",
        "private_key",
        "public_key",
        "redis_password",
        "secret",
        "token",
        "token_url",
    }
)

# A bare "_key" suffix is included deliberately. It was initially left out for
# fear of catching legitimate analytics fields such as `partition_key` or
# `routing_key`, but those live in event broker config, which is never
# reported (only its `type`). Across the whole repo the only `*_key` config keys
# in reported sections are credentials, while provider-specific spellings that a
# curated list keeps missing (`openai_key`, `pi_key`, ...) are real and common.
# "_auth" catches credentials passed as a positional list rather than under a
# named key -- `neo4j_auth: ["neo4j", "<password>"]` is real and appears in
# production. List items are visited with no key name of their own, so nothing
# inside the list can ever match; the whole value has to go. Note `oauth` does
# NOT match this suffix ("oauth".endswith("_auth") is False), so OAuth container
# blocks still recurse and have their nested `client_secret` redacted
# individually.
REDACTED_CONFIG_KEY_SUFFIXES = ("_password", "_secret", "_token", "_key", "_auth")

# Keys whose value is a URL or DSN that can embed a credential in its userinfo
# or query string, where matching on the key name alone would miss the secret.
URL_CONFIG_KEYS = frozenset(
    {
        "agent_card",
        "api_base",
        "base_url",
        "connection_string",
        "dsn",
        "endpoint",
        # Provider proxy settings routinely carry basic-auth credentials inline.
        "openai_proxy",
        "push_notification_url",
        "redis_url",
        "uri",
        "url",
    }
)

# Matched as well as the exact names above, because provider-specific variants of
# "some kind of endpoint" are open-ended and a curated list cannot keep up.
URL_CONFIG_KEY_SUFFIXES = ("_url", "_uri", "_proxy", "_endpoint", "_base")

# Free-form mappings where any key could hold a secret, so no key-name check can
# be trusted. Their values are dropped and replaced by the key names alone.
KEYS_ONLY_MAPPINGS = frozenset({"additional_params", "auth", "static"})

# Model-group connection/infra detail with no product-analytics value -- not a
# secret (already-redacted or non-sensitive), just noise in the payload.
#
# NOT part of the default redaction: callers opt in per data set via
# `redact_config_secrets`'s `drop_keys` argument instead of this being dropped
# everywhere, since a key name here could carry real analytics value in a
# different data set.
MODEL_CONFIG_NOISE_KEYS = frozenset(
    {
        "api_base",
        "api_version",
        "cache_folder",
    }
)

REDACTED_VALUE = "<redacted>"

# Sentinel returned by `_redact_config_entry` for a key that should be
# dropped from the output entirely, as opposed to redacted in place.
_DROPPED = object()


def normalize_config_key(key: str) -> str:
    """Fold a config key to the form the match lists are written in.

    Header-style names arrive hyphenated (`api-key` is Azure OpenAI's own
    required header, and `Authorization` is capitalised), so matching on the raw
    string would miss real credentials.
    """
    return key.lower().replace("-", "_")


def is_secret_config_key(key: str) -> bool:
    """Whether a config key holds a credential that must not be reported."""
    normalized = normalize_config_key(key)
    return normalized in REDACTED_CONFIG_KEYS or normalized.endswith(
        REDACTED_CONFIG_KEY_SUFFIXES
    )


def is_url_config_key(key: str) -> bool:
    """Whether a config key's value is a URL that may embed a credential."""
    normalized = normalize_config_key(key)
    return normalized in URL_CONFIG_KEYS or normalized.endswith(URL_CONFIG_KEY_SUFFIXES)


def _redact_config_entry(
    key: Any, value: Any, drop_keys: FrozenSet[str]
) -> Tuple[Any, Any]:
    """Redact one config entry, returning its possibly renamed key and value."""
    if not isinstance(key, str):
        return key, redact_config_secrets(value, drop_keys)

    # Order matters: full redaction wins over URL stripping, so a key such as
    # `token_url` loses its whole value rather than just its userinfo.
    if is_secret_config_key(key):
        return key, REDACTED_VALUE
    normalized = normalize_config_key(key)
    if normalized in drop_keys:
        return key, _DROPPED
    if normalized in KEYS_ONLY_MAPPINGS:
        if isinstance(value, dict):
            return f"{key}_keys", sorted(str(inner_key) for inner_key in value)
        if not isinstance(value, (bool, int, float, type(None))):
            # A free-form mapping holding something other than a mapping, e.g.
            # `auth: "Bearer <token>"` or `auth: ["Bearer <token>"]`. Neither is
            # observed in production, but both would otherwise match no key and
            # no suffix and pass through in the clear -- a list especially so,
            # since its items are visited with no key name of their own.
            #
            # Expressed as "anything that is not a plain scalar" rather than as
            # a list of types to redact, so a shape nobody has thought of yet
            # fails safe. Booleans and numbers are passed through because they
            # cannot carry a credential, and `auth: false` does occur and
            # carries a small analytics signal.
            return key, REDACTED_VALUE
    if is_url_config_key(key):
        if isinstance(value, str):
            return key, strip_url_credentials(value)
        if isinstance(value, list):
            # A list of endpoints, e.g. `url: ["redis://user:pass@host", ...]`.
            # Stripped item by item rather than redacted wholesale, so each
            # host survives for analytics exactly as a single value would.
            # Recursing instead would visit the items with no key name and
            # leave any embedded credential in place.
            return key, [
                strip_url_credentials(item)
                if isinstance(item, str)
                else redact_config_secrets(item, drop_keys)
                for item in value
            ]
    return key, redact_config_secrets(value, drop_keys)


def redact_config_secrets(value: Any, drop_keys: FrozenSet[str] = frozenset()) -> Any:
    """Recursively strip credentials out of config data bound for telemetry.

    Customers may hardcode a literal secret into any config field instead of
    referencing an environment variable, and the validation that rejects this
    runs after the training telemetry event has already been sent. Rather than
    trusting the shape of a value, anything credential-shaped is dropped on the
    way out.

    The walk is structural rather than path-specific because provider config
    shapes differ per provider and grow over time, so a new provider field is
    covered without a matching change here.

    Args:
        value: Config data of any shape -- a parsed `endpoints.yml` /
            `config.yml` section, or the output of a Pydantic `model_dump`.
        drop_keys: Additional, non-secret keys to drop from the output
            entirely (see e.g. `MODEL_CONFIG_NOISE_KEYS`). Opt-in per call
            site rather than a global default, since a key name here may
            carry real analytics value in a different data set.

    Returns:
        A new structure with credentials (and any `drop_keys`) removed. The
        input is never mutated, since callers pass live configuration still
        in use for training.
    """
    if isinstance(value, dict):
        redacted: Dict[Any, Any] = {}
        for key, item in value.items():
            redacted_key, redacted_value = _redact_config_entry(key, item, drop_keys)
            if redacted_value is _DROPPED:
                continue
            redacted[redacted_key] = redacted_value
        return redacted
    if isinstance(value, list):
        return [redact_config_secrets(item, drop_keys) for item in value]
    return value
